package br.com.marquesautodetail.api.avaliacao; import br.com.marquesautodetail.api.avaliacao.dto.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController public class AvaliacaoController{ private final AvaliacaoService service; public AvaliacaoController(AvaliacaoService service){this.service=service;} @PostMapping("/avaliacoes") public AvaliacaoResponse criar(@RequestBody AvaliacaoRequest r){return service.criar(r);} @GetMapping("/empresas/{empresaId}/avaliacoes") public List<AvaliacaoResponse> porEmpresa(@PathVariable Long empresaId){return service.porEmpresa(empresaId);} }
